        pq = [(0, start)]
        dist = {start: 0}
        while pq:
            cost, node = heapq.heappop(pq)
            if cost > dist[node]:
                continue
            for neighbor, edge_cost in graph[node]:
                new_cost = cost + edge_cost
                if neighbor not in dist or new_cost < dist[neighbor]:
                    dist[neighbor] = new_cost
                    heapq.heappush(pq, (new_cost, neighbor))
        return dist

    max_flow = 0
    total_cost = 0
