            return -1
        current_node = i
        while current_node != 0:
            for neighbor, edge_cost in graph[current_node]:
                if neighbor == 0:
                    total_cost += edge_cost
                    break
                if dist[neighbor] + edge_cost == dist[current_node]:
                    current_node = neighbor
                    visited.add(current_node)
